#!/usr/bin/env bash
set -Eeuo pipefail
TARGET='/home/agent/ssh-mcp-server/src/plugins/hostActions.js'
EXPECTED_OLD='48d94fe8a47216e36ac4430a845c3441912b45484920628dd03fd3c2cb487312'
EXPECTED_NEW='c4d72071fa0bcedc18a159f0e195ebe3b4356a239a6426f90fe7ffd38f81ecd3'
SERVICE='prhm-agent-mcp.service'
BACKUP_DIR='/var/backups/prhm-agent-mcp-central-offsite-registration-v1'
mkdir -p "$BACKUP_DIR"
CURRENT="$(sha256sum "$TARGET" | awk '{print $1}')"
if [[ "$CURRENT" == "$EXPECTED_NEW" ]]; then
  /usr/bin/node --check "$TARGET"
  systemctl is-active --quiet prhm-agent-mcp.service
  echo 'AGENT_MCP_CENTRAL_OFFSITE_REGISTRATION=ALREADY_APPLIED'
  exit 0
fi
[[ "$CURRENT" == "$EXPECTED_OLD" ]] || { echo "PREIMAGE_SHA_MISMATCH:$CURRENT" >&2; exit 41; }
TMP="$(mktemp /tmp/prhm-agent-mcp-central-offsite.XXXXXX.js)"
BACKUP="$BACKUP_DIR/hostActions.js.$(date -u +%Y%m%dT%H%M%SZ).$EXPECTED_OLD.bak"
rollback() {
  rc=$?
  set +e
  if [[ -f "$BACKUP" ]]; then
    install -m 0644 "$BACKUP" "$TARGET"
    systemctl restart prhm-agent-mcp.service
  fi
  rm -f "$TMP"
  echo 'ROLLBACK_PERFORMED=1' >&2
  exit "$rc"
}
trap rollback ERR
printf '%s' '' | base64 -d > "$TMP"
[[ "$(sha256sum "$TMP" | awk '{print $1}')" == "$EXPECTED_NEW" ]]
/usr/bin/node --check "$TMP"
cp -a "$TARGET" "$BACKUP"
install -m 0644 "$TMP" "$TARGET"
[[ "$(sha256sum "$TARGET" | awk '{print $1}')" == "$EXPECTED_NEW" ]]
/usr/bin/node --check "$TARGET"
systemctl restart prhm-agent-mcp.service
systemctl is-active --quiet prhm-agent-mcp.service
rm -f "$TMP"
trap - ERR
echo 'AGENT_MCP_CENTRAL_OFFSITE_REGISTRATION=APPLIED'
echo "LIVE_SHA256=$EXPECTED_NEW"
echo "BACKUP=$BACKUP"
